    proof { const_facts(); }
    self.page_ptr.addr() > segment.get_page_header_ptr(0).page_ptr.addr()
}

#[inline(always)]
pub fn get_index(&self) -> (idx: usize)
    requires self.wf(),
ensures
    idx == self.page_id@.idx,

